source('validation/autodesn/remediation/import_sbc_shard.R')
d<-tempfile();dir.create(d);src<-file.path(d,'src');dst<-file.path(d,'dst');dir.create(src);dir.create(dst)
contract<-list(id='contract',contract=list(replications=200L))
saveRDS(contract,file.path(src,'contract.rds'));saveRDS(contract,file.path(dst,'contract.rds'))
x<-list(contract_id='contract',case=1L,u=c(a=.2,b=.4),ess=c(a=500,b=700),target_id=paste(rep('a',64),collapse=''),computation=list(elapsed_seconds=1,proposals=20L),truth=list(variance=.5),frozen_geometry_verified=TRUE,causal_design_reconstruction_verified=TRUE)
saveRDS(x,file.path(src,'case_1.rds'))
a<-remediation_import_sbc_shard(src,dst,1L,file.path(d,'one.json'))
stopifnot(a$all_selected_cases_verified,a$records[[1]]$action=='imported',identical(readBin(file.path(src,'case_1.rds'),'raw',n=100000),readBin(file.path(dst,'case_1.rds'),'raw',n=100000)))
x$computation$elapsed_seconds<-2;saveRDS(x,file.path(src,'case_1.rds'))
b<-remediation_import_sbc_shard(src,dst,1L,file.path(d,'two.json'),TRUE);stopifnot(b$all_selected_cases_verified,b$independent_replications_added==0L)
x$u[1]<-.9;saveRDS(x,file.path(src,'case_1.rds'))
stopifnot(inherits(try(remediation_import_sbc_shard(src,dst,1L,file.path(d,'bad.json'),TRUE),silent=TRUE),'try-error'))
contract$id<-'wrong';saveRDS(contract,file.path(src,'contract.rds'))
stopifnot(inherits(try(remediation_import_sbc_shard(src,dst,1L,file.path(d,'badcontract.json'),TRUE),silent=TRUE),'try-error'))
unlink(d,recursive=TRUE)
jsonlite::write_json(list(complete=TRUE,atomic_exact_binary_import=TRUE,elapsed_only_duplicate_difference_allowed=TRUE,changed_ranks_rejected=TRUE,changed_contract_rejected=TRUE,independent_replications_added=0L,scope='Synthetic provenance/import checks, not posterior calibration'), 'validation/autodesn/remediation/evidence/sbc_shard_import_tests.json',pretty=TRUE,auto_unbox=TRUE)
cat('Shard import controls passed\n')
